/**
 * fullDictionary.ts - Lazy, offline loader for the Hunspell-derived 5-letter word lists
 * (data/words-{de,en}.ts, generated by scripts/build-wordle-words.mjs). Each list is its own
 * chunk, precached by the service worker. Until loaded, validation falls back to the small
 * curated lists (see dictionary.ts).
 */

export type WordleDictLang = 'de' | 'en';

const WORD_LENGTH = 5;
const cache = new Map<WordleDictLang, ReadonlySet<string>>();
const pending = new Map<WordleDictLang, Promise<ReadonlySet<string>>>();

export function toDictLang(lang: string): WordleDictLang {
  return lang.startsWith('de') ? 'de' : 'en';
}

/** Splits a fixed-width string of concatenated words into a Set. */
export function parseWordString(packed: string): ReadonlySet<string> {
  const words = new Set<string>();
  for (let i = 0; i + WORD_LENGTH <= packed.length; i += WORD_LENGTH) {
    words.add(packed.slice(i, i + WORD_LENGTH));
  }
  return words;
}

/** The full list if it has been loaded already, otherwise undefined. */
export function getLoadedFullDictionary(lang: string): ReadonlySet<string> | undefined {
  return cache.get(toDictLang(lang));
}

/** Loads (once) the full list of a language. Rejected loads can be retried. */
export function loadFullDictionary(lang: string): Promise<ReadonlySet<string>> {
  const key = toDictLang(lang);
  const cached = cache.get(key);
  if (cached) return Promise.resolve(cached);
  const inflight = pending.get(key);
  if (inflight) return inflight;

  const packed =
    key === 'de'
      ? import('../data/words-de').then((mod) => mod.DE_WORDS)
      : import('../data/words-en').then((mod) => mod.EN_WORDS);
  const promise = packed
    .then((str) => {
      const words = parseWordString(str);
      cache.set(key, words);
      return words;
    })
    .finally(() => pending.delete(key));
  pending.set(key, promise);
  return promise;
}
